-- Fix cascades, immutable audit accounting, and subsequent-period settlement.
DROP TRIGGER history_quota;
DROP TRIGGER history_budget;
UPDATE WorkflowBudget SET bytes=(SELECT coalesce(sum(coalesce(length(CAST(beforeJson AS BLOB)),0)+coalesce(length(CAST(afterJson AS BLOB)),0)+300),0) FROM BusinessHistory),rows=(SELECT count(*) FROM BusinessHistory) WHERE name='history';
CREATE TRIGGER history_quota BEFORE INSERT ON BusinessHistory WHEN (SELECT bytes+coalesce(length(CAST(NEW.beforeJson AS BLOB)),0)+coalesce(length(CAST(NEW.afterJson AS BLOB)),0)+300>52428800 OR rows>=50000 FROM WorkflowBudget WHERE name='history') BEGIN SELECT RAISE(ABORT,'WORKFLOW_QUOTA'); END;
CREATE TRIGGER history_budget AFTER INSERT ON BusinessHistory BEGIN UPDATE WorkflowBudget SET bytes=bytes+coalesce(length(CAST(NEW.beforeJson AS BLOB)),0)+coalesce(length(CAST(NEW.afterJson AS BLOB)),0)+300,rows=rows+1 WHERE name='history'; END;
CREATE TABLE BusinessWriteReservation(businessId TEXT PRIMARY KEY,id TEXT NOT NULL,expiresAt INTEGER NOT NULL,reservedBytes INTEGER NOT NULL,reservedRows INTEGER NOT NULL);
DROP TRIGGER lock_Invoice_UPDATE;
CREATE TRIGGER lock_Invoice_UPDATE BEFORE UPDATE ON Invoice WHEN (EXISTS(SELECT 1 FROM BusinessControl WHERE businessId=OLD.businessId AND closedThrough IS NOT NULL AND date(OLD.issueDate)<=closedThrough) OR EXISTS(SELECT 1 FROM BusinessControl WHERE businessId=NEW.businessId AND closedThrough IS NOT NULL AND date(NEW.issueDate)<=closedThrough)) AND NOT(OLD.status='SENT' AND NEW.status='PAID' AND NEW.id IS OLD.id AND NEW.businessId IS OLD.businessId AND NEW.partnerId IS OLD.partnerId AND NEW.invoiceNumber IS OLD.invoiceNumber AND NEW.issueDate IS OLD.issueDate AND NEW.dueDate IS OLD.dueDate AND NEW.notes IS OLD.notes AND NEW.subtotal IS OLD.subtotal AND NEW.taxAmount IS OLD.taxAmount AND NEW.total IS OLD.total AND NEW.createdAt IS OLD.createdAt) BEGIN SELECT RAISE(ABORT,'PERIOD_LOCKED'); END;
DROP TRIGGER history_JournalEntryLine_DELETE;
CREATE TRIGGER history_JournalEntryLine_DELETE AFTER DELETE ON JournalEntryLine WHEN EXISTS(SELECT 1 FROM JournalEntry WHERE id=OLD.journalEntryId) BEGIN INSERT INTO BusinessHistory(businessId,entityType,entityId,action,beforeJson,afterJson) VALUES ((SELECT businessId FROM JournalEntry WHERE id=OLD.journalEntryId),'JournalEntryLine',OLD.id,'DELETE',json_object('id',OLD.id,'journalEntryId',OLD.journalEntryId,'lineNumber',OLD.lineNumber,'side',OLD.side,'accountId',OLD.accountId,'subAccountId',OLD.subAccountId,'partnerId',OLD.partnerId,'taxCategoryId',OLD.taxCategoryId,'amount',OLD.amount,'taxAmount',OLD.taxAmount,'description',OLD.description),NULL); END;
CREATE TRIGGER cascade_history_JournalEntry BEFORE DELETE ON JournalEntry BEGIN INSERT INTO BusinessHistory(businessId,entityType,entityId,action,beforeJson,afterJson) SELECT OLD.businessId,'JournalEntryLine',c.id,'DELETE',json_object('id',c.id,'journalEntryId',c.journalEntryId,'lineNumber',c.lineNumber,'side',c.side,'accountId',c.accountId,'subAccountId',c.subAccountId,'partnerId',c.partnerId,'taxCategoryId',c.taxCategoryId,'amount',c.amount,'taxAmount',c.taxAmount,'description',c.description),NULL FROM JournalEntryLine c WHERE c.journalEntryId=OLD.id; END;
